bodyHtml:
{% if data.lang|default('') == 'es' %}<p><strong>Sent from the Spanish site: reply in Spanish.</strong></p>{% endif %}
{% set home = cms.collection.object('listings', data.listing) %}
<p><strong>{{ data.name|e }}</strong>, {{ data.email|e }}{% if data.phone %}, {{ data.phone|e }}{% endif %}</p>
<p>Would like to see <strong>{{ home.address|default(data.listing)|e }}</strong>{% if not home.mine|default(true) %} ({{ home.agentName|e }}'s listing){% endif %}<br>
{% if data.date %}{{ data.date|date('l, F j') }}, {% endif %}{{ {'morning': 'morning', 'afternoon': 'afternoon', 'evening': 'evening'}[data.times]|default(data.times)|e }}</p>
{% if data.message %}<p>{{ data.message|e|nl2br }}</p>{% endif %}
<p>It is saved in the admin under Showing Requests.</p>
